  }
  const token = await getToken();
  if (!token) return;
  const classIds = (courses || [])
    .map((c) => Number(c.id || c.ID || 0))
    .filter((id) => id > 0);
  if (classIds.length === 0) {
    directorSessionsByClassId.value = {};
